namespace StrataRec.IntegrationTests;

/// <summary>
/// The test assembly's entry point, in place of the one xUnit.net generates (<c>XunitAutoGeneratedEntryPoint</c> is
/// off): a test runs the assembly in a child process when what the test checks could end the process
/// (<see cref="TimerFaultTests"/>) or happens once per process (<see cref="InstrumentPublishedFaultTests"/>).
/// </summary>
internal static class Program
{
    public static int Main(string[] args) =>
        args switch
        {
            ["timer-fault", var site] => TimerFaultChild.Run(site),
            ["cancel-then-dispose"] => TimerFaultChild.CancelThenDispose(),
            ["cancel-races"] => TimerFaultChild.CancelRaces(),
            ["instrument-published-fault"] => InstrumentPublishedFaultChild.Run(),
            _ when Array.IndexOf(args, "-automated") >= 0 || Array.IndexOf(args, "@@") >= 0 =>
                Xunit.Runner.InProc.SystemConsole.ConsoleRunner.Run(args).GetAwaiter().GetResult(),
            _ => Xunit.MicrosoftTestingPlatform.TestPlatformTestFramework.RunAsync(args, SelfRegisteredExtensions.AddSelfRegisteredExtensions).GetAwaiter().GetResult(),
        };
}
